var findWords = function(board, words) {
    if (!board || !board.length || !board[0].length) return [];
    const TERMINAL = '$';
    const trie = {};
    for (const word of words) {
        let node = trie;
        for (const ch of word) {
            if (!node[ch]) node[ch] = {};
            node = node[ch];
        }
        node[TERMINAL] = word;
    }
    const rows = board.length, cols = board[0].length;
    const found = [];
    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const search = (row, col, parent) => {
        const ch = board[row][col];
        const node = parent[ch];
        if (node === undefined) return;
        if (Object.prototype.hasOwnProperty.call(node, TERMINAL)) {
            found.push(node[TERMINAL]);
            delete node[TERMINAL];
        }
        board[row][col] = '#';
        for (const [dr, dc] of dirs) {
            const nr = row + dr, nc = col + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc] !== '#') {
                search(nr, nc, node);
            }
        }
        board[row][col] = ch;
        if (Object.keys(node).length === 0) delete parent[ch];
    };
    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < cols; col++) {
            search(row, col, trie);
        }
    }
    return found;
};

