from typing import List


class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        if not board or not board[0]:
            return []

        terminal = '$'
        trie = {}
        for word in words:
            node = trie
            for ch in word:
                node = node.setdefault(ch, {})
            node[terminal] = word

        rows, cols = len(board), len(board[0])
        found = []

        def search(row: int, col: int, parent: dict) -> None:
            ch = board[row][col]
            node = parent.get(ch)
            if node is None:
                return

            word = node.pop(terminal, None)
            if word is not None:
                found.append(word)

            board[row][col] = '#'
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = row + dr, col + dc
                if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != '#':
                    search(nr, nc, node)
            board[row][col] = ch

            if not node:
                parent.pop(ch, None)

        for row in range(rows):
            for col in range(cols):
                search(row, col, trie)

        return found
